#!/usr/bin/env python3
import argparse,base64,hashlib,json,os,shutil,subprocess,time,zlib
from pathlib import Path
parser=argparse.ArgumentParser()
parser.add_argument('--root',default='/opt/akira')
parser.add_argument('--check-only',action='store_true')
parser.add_argument('--apk',action='store_true')
args=parser.parse_args()
root=Path(args.root).resolve()
payload=json.loads(zlib.decompress(base64.b64decode('')))
for name,digest in payload['hashes'].items():
    path=root/name
    if not path.exists() or hashlib.sha256(path.read_bytes()).hexdigest()!=digest:
        if path.exists() and path.read_text()==payload['files'][name]: continue
        raise SystemExit('STOP: source changed: '+name+'. No files changed. Send a fresh source archive.')
if args.check_only:
    print('SOURCE CHECK OK');raise SystemExit(0)
backup=root/'backups'/('control-'+str(time.time_ns()))
backup.mkdir(parents=True)
for name,content in payload['files'].items():
    dest=root/name
    if dest.exists():
        copy=backup/name;copy.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(dest,copy)
    dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(content)
print('Backup: '+str(backup),flush=True)
def run(cmd,cwd=None,env=None):
    subprocess.run(cmd,cwd=cwd or root/'server',env=env,check=True)
for name in ['control.mjs','server.mjs','admin-panel.mjs','game-bets.mjs']:
    run(['node','--check',str(root/'server/src'/name)])
run(['docker','compose','build','akira-api'])
run(['docker','compose','run','--rm','--no-deps','-T','akira-api','node','--max-old-space-size=64','--input-type=module','-e',"await import('./src/server.mjs'); console.log('IMPORT OK')"])
run(['docker','compose','run','--rm','--no-deps','-T','akira-api','node','--max-old-space-size=64','src/control-migrate.mjs'])
run(['docker','compose','up','-d','akira-api'])
import urllib.request
for attempt in range(30):
    try:
        with urllib.request.urlopen('http://127.0.0.1:4301/health',timeout=2) as response:
            if response.status==200:break
    except Exception:
        if attempt==29:raise SystemExit('Health check failed. Run docker compose logs --tail=50 akira-api. Backup: '+str(backup))
        time.sleep(1)
print('ADMIN LIVE: https://api.soverixnet.online/admin/?v=control-2',flush=True)
if args.apk:
    apk_name='Akira-Voice-Chat.apk'
    for folder in ['web','dist']:
        p=root/folder/apk_name
        if p.exists():
            shutil.copy2(p,backup/(folder+'-previous.apk'))
    embedded=root/'web'/apk_name
    if embedded.exists():embedded.unlink()
    try:
        run(['npm','run','build'],root)
        run(['npx','cap','sync','android'],root)
        env=os.environ.copy();env['ANDROID_HOME']='/opt/android-sdk';env['ANDROID_SDK_ROOT']='/opt/android-sdk'
        run(['bash','gradlew','assembleDebug','--no-daemon','--max-workers=1','-Dorg.gradle.jvmargs=-Xmx768m -XX:MaxMetaspaceSize=384m'],root/'android',env)
        apk=root/'android/app/build/outputs/apk/debug/app-debug.apk'
        for folder in ['dist','web']:
            out=root/folder/apk_name;out.parent.mkdir(exist_ok=True);shutil.copy2(apk,out);out.chmod(0o644)
    except Exception:
        for folder in ['web','dist']:
            old=backup/(folder+'-previous.apk')
            if old.exists():shutil.copy2(old,root/folder/apk_name)
        raise
    print('APK READY: https://voice.soverixnet.online/Akira-Voice-Chat.apk?v=control-2')
else:
    print('App source updated. Rebuild the APK to use Community, server gifts and store.')
